import { BuildOptions, Page } from './ssg';

export interface PluginContext {
  options: BuildOptions;
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  pages: Page[];
  writtenFiles: string[];
  [key: string]: unknown;
}

export interface Plugin {
  name: string;
  onStart?(context: PluginContext): void | Promise<void>;
  beforeBuild?(context: PluginContext): void | Promise<void>;
  onFile?(page: Page, context: PluginContext): Page | void | Promise<Page | void>;
  afterBuild?(context: PluginContext): void | Promise<void>;
  onEnd?(context: PluginContext): void | Promise<void>;
}

type LifecycleHook = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd';

export function createPluginContext(options: BuildOptions): PluginContext {
  return {
    options,
    contentDir: options.contentDir,
    outputDir: options.outputDir,
    templatesDir: options.templatesDir ?? './templates',
    pages: [],
    writtenFiles: [],
  };
}

export function runSyncHooks(
  plugins: Plugin[],
  hook: LifecycleHook,
  context: PluginContext
): void {
  for (const plugin of plugins) {
    const fn = plugin[hook] as ((context: PluginContext) => void | Promise<void>) | undefined;
    if (fn) {
      fn.call(plugin, context);
    }
  }
}

export function runHooksAsync(
  plugins: Plugin[],
  hook: LifecycleHook,
  context: PluginContext
): Promise<void> {
  return plugins.reduce(
    (chain, plugin) =>
      chain.then(async () => {
        const fn = plugin[hook] as ((context: PluginContext) => void | Promise<void>) | undefined;
        if (fn) {
          await fn.call(plugin, context);
        }
      }),
    Promise.resolve()
  );
}

export function applyOnFile(plugins: Plugin[], page: Page, context: PluginContext): Page {
  let current = page;
  for (const plugin of plugins) {
    const fn = plugin.onFile;
    if (fn) {
      const result = fn.call(plugin, current, context);
      if (result != null) {
        current = result;
      }
    }
  }
  return current;
}

export function applyOnFileAsync(
  plugins: Plugin[],
  page: Page,
  context: PluginContext
): Promise<Page> {
  return plugins.reduce(
    (chain, plugin) =>
      chain.then(async (current) => {
        const fn = plugin.onFile;
        if (!fn) {
          return current;
        }
        const result = await fn.call(plugin, current, context);
        return result ?? current;
      }),
    Promise.resolve(page)
  );
}

import { Frontmatter, Page, markdownToHtml, normalizeTags, parseFrontmatter } from '../ssg';
import { Plugin, PluginContext } from '../plugin';

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  parseFrontmatter(raw: string): { frontmatter: Frontmatter; content: string } {
    return parseFrontmatter(raw);
  }

  normalizeTags(tags: Frontmatter['tags']): string[] {
    return normalizeTags(tags);
  }

  markdownToHtml(markdown: string): string {
    return markdownToHtml(markdown);
  }

  render(page: Page): Page {
    if (page.content === undefined) {
      return page;
    }
    return { ...page, html: this.markdownToHtml(page.content) };
  }

  onFile(page: Page, _context: PluginContext): Page {
    return this.render(page);
  }
}

import { Page } from '../ssg';
import { Plugin, PluginContext } from '../plugin';
import { TemplateEngine } from '../template-engine';

export class TemplatePlugin implements Plugin {
  name = 'template';
  private engine: TemplateEngine;

  constructor(options: { templatesDir?: string } = {}) {
    this.engine = new TemplateEngine({ templatesDir: options.templatesDir });
  }

  beforeBuild(context: PluginContext): void {
    this.engine = new TemplateEngine({ templatesDir: context.templatesDir });
  }

  renderPage(page: Page): string {
    return this.engine.renderPage(page);
  }

  renderIndex(pages: Page[]): string {
    return this.engine.renderIndex(pages);
  }
}

import { Plugin } from '../plugin';
import { DevServer, DevServerOptions } from '../dev-server';

export class DevServerPlugin implements Plugin {
  name = 'dev-server';

  createServer(options: DevServerOptions): DevServer {
    return new DevServer(options);
  }
}

export { MarkdownPlugin } from './markdown';
export { TemplatePlugin } from './template';
export { DevServerPlugin } from './dev-server';

import * as fs from 'fs';
import * as path from 'path';
import { Plugin } from './plugin';

export type PluginModule = Plugin | (new () => Plugin) | string;

export interface SSGConfig {
  plugins?: PluginModule[];
}

interface CompiledModule {
  filename: string;
  paths: string[];
  _compile: (code: string, filename: string) => void;
  exports: unknown;
}

function transpile(source: string): string {
  const ts = require('typescript');
  return ts.transpileModule(source, {
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2020,
      esModuleInterop: true,
    },
  }).outputText;
}

function loadTsModule(filePath: string): unknown {
  const source = fs.readFileSync(filePath, 'utf8');
  const js = transpile(source);

  const ModuleCtor = require('module');
  const mod: CompiledModule = new ModuleCtor(filePath, module);
  mod.filename = filePath;
  mod.paths = ModuleCtor._nodeModulePaths(path.dirname(filePath));
  mod._compile(js, filePath);
  return mod.exports;
}

function isPlugin(value: unknown): value is Plugin {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof (value as { name?: unknown }).name === 'string'
  );
}

function isPluginClass(value: unknown): value is new () => Plugin {
  return typeof value === 'function';
}

function normalizePlugin(candidate: unknown): Plugin | undefined {
  if (isPlugin(candidate)) {
    return candidate;
  }
  if (isPluginClass(candidate)) {
    return new candidate();
  }
  return undefined;
}

function resolvePluginModulePath(entry: string, rootDir: string): string {
  const pluginsDir = path.join(rootDir, 'plugins');
  const base = path.isAbsolute(entry) ? entry : path.join(rootDir, entry);
  const candidates = [base, `${base}.ts`, path.join(pluginsDir, entry), `${path.join(pluginsDir, entry)}.ts`];
  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) {
      return candidate;
    }
  }
  throw new Error(`Plugin module not found: ${entry}`);
}

function resolvePluginEntry(entry: PluginModule, rootDir: string): Plugin | undefined {
  if (typeof entry === 'string') {
    const modPath = resolvePluginModulePath(entry, rootDir);
    const exports = loadTsModule(modPath) as { default?: unknown; plugin?: unknown };
    return normalizePlugin(exports.default ?? exports.plugin ?? exports);
  }
  return normalizePlugin(entry);
}

export function loadConfiguredPlugins(rootDir: string = process.cwd()): Plugin[] {
  const configPath = path.join(rootDir, 'ssg.config.ts');
  if (!fs.existsSync(configPath)) {
    return [];
  }

  let config: SSGConfig;
  try {
    const exports = loadTsModule(configPath) as { default?: SSGConfig };
    config = (exports.default ?? exports) as SSGConfig;
  } catch (err) {
    console.warn(`Failed to load ${configPath}: ${(err as Error).message}`);
    return [];
  }

  const plugins: Plugin[] = [];
  for (const entry of config.plugins ?? []) {
    try {
      const plugin = resolvePluginEntry(entry, rootDir);
      if (plugin) {
        plugins.push(plugin);
      }
    } catch (err) {
      console.warn(`Failed to load plugin ${String(entry)}: ${(err as Error).message}`);
    }
  }
  return plugins;
}

import * as fs from 'fs';
import * as path from 'path';
import { BuildOptions, Page, normalizeTags, parseFrontmatter } from './ssg';
import { Plugin, PluginContext, applyOnFile, createPluginContext, runSyncHooks } from './plugin';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/template';
import { loadConfiguredPlugins } from './load-plugins';

function slugFromFilename(filename: string): string {
  const ext = path.extname(filename);
  return filename.slice(0, filename.length - ext.length);
}

/** Recursively collect all .md file paths under a directory, sorted by path. */
export function findMarkdownFiles(contentDir: string): string[] {
  const results: string[] = [];

  function walk(dir: string): void {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    entries.sort((a, b) => a.name.localeCompare(b.name));
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
        results.push(full);
      }
    }
  }

  if (fs.existsSync(contentDir)) {
    walk(contentDir);
  }
  return results;
}

function loadRawPages(contentDir: string): Page[] {
  const files = findMarkdownFiles(contentDir);
  const pages: Page[] = [];

  for (const file of files) {
    const raw = fs.readFileSync(file, 'utf8');
    const { frontmatter, content } = parseFrontmatter(raw);
    const slug = slugFromFilename(path.basename(file));
    pages.push({
      slug,
      title: frontmatter.title || slug,
      date: frontmatter.date,
      tags: normalizeTags(frontmatter.tags),
      html: '',
      content,
      template: frontmatter.template,
      layout: frontmatter.layout,
      frontmatter,
    });
  }

  return pages.sort((a, b) => {
    const ad = a.date || '';
    const bd = b.date || '';
    if (ad === bd) {
      return a.title.localeCompare(b.title);
    }
    return ad < bd ? 1 : -1;
  });
}

export function loadPages(contentDir: string): Page[] {
  const markdown = new MarkdownPlugin();
  return loadRawPages(contentDir).map((page) => markdown.render(page));
}

export interface BuildResult {
  outputDir: string;
  writtenFiles: string[];
}

export function build(options: BuildOptions): BuildResult {
  const markdown = new MarkdownPlugin();
  const template = new TemplatePlugin({ templatesDir: options.templatesDir });
  const plugins: Plugin[] = [markdown, template, ...loadConfiguredPlugins()];

  const context: PluginContext = createPluginContext(options);

  runSyncHooks(plugins, 'onStart', context);
  runSyncHooks(plugins, 'beforeBuild', context);

  const pages: Page[] = loadRawPages(options.contentDir).map((page) =>
    applyOnFile(plugins, page, context)
  );
  context.pages = pages;

  fs.mkdirSync(options.outputDir, { recursive: true });

  const writtenFiles: string[] = [];

  const indexHtml = template.renderIndex(pages);
  const indexPath = path.join(options.outputDir, 'index.html');
  fs.writeFileSync(indexPath, indexHtml, 'utf8');
  writtenFiles.push(indexPath);

  for (const page of pages) {
    const pageHtml = template.renderPage(page);
    const pagePath = path.join(options.outputDir, `${page.slug}.html`);
    fs.writeFileSync(pagePath, pageHtml, 'utf8');
    writtenFiles.push(pagePath);
  }

  context.writtenFiles = writtenFiles;
  runSyncHooks(plugins, 'afterBuild', context);
  runSyncHooks(plugins, 'onEnd', context);

  return { outputDir: options.outputDir, writtenFiles };
}

